16	package org.springframework.samples.petclinic.util;
17	
18	/**
19	 * Computes the Luhn check digit over the digits contained in a string.
20	 *
21	 * <p>Non-digit characters are ignored, so the algorithm can be applied directly to
22	 * formatted identifiers (such as a hyphenated customer code). Standard Luhn: working
23	 * from the rightmost digit, every second digit is doubled (subtracting 9 when the
24	 * result exceeds 9), the digits are summed, and the check digit is the amount that
25	 * rounds the sum up to the next multiple of ten.
26	 */
27	public final class Luhn {
28	
29	    private Luhn() {
30	    }
31	
32	    /**
33	     * Return the Luhn check digit (0-9) over the digits contained in {@code value}.
34	     *
35	     * @param value the source string; non-digit characters are ignored
36	     * @return the single check digit, from 0 to 9
37	     */
38	    public static int checkDigit(String value) {
39	        int sum = 0;
40	        boolean doubling = true;
41	        for (int i = value.length() - 1; i >= 0; i--) {
42	            char c = value.charAt(i);
43	            if (c < '0' || c > '9') {
44	                continue;
45	            }
46	            int d = c - '0';
47	            if (doubling) {
48	                d *= 2;
49	                if (d > 9) {
50	                    d -= 9;
51	                }
52	            }
53	            sum += d;
54	            doubling = !doubling;
55	        }
56	        return (10 - (sum % 10)) % 10;
57	    }
58	}
