16	package org.springframework.samples.petclinic.util;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * Renders SHA-256 digests as hexadecimal. Shared by the stable identifiers the application derives
24	 * from owner fields — the household id and customer code (an upper-case prefix) and the identity key
25	 * (the full lower-case digest) — so the digest and hex-encoding logic lives in one place.
26	 */
27	public final class Sha256 {
28	
29	    private Sha256() {
30	    }
31	
32	    /**
33	     * Produce the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
34	     * bytes of {@code input}.
35	     *
36	     * @param input the value to hash
37	     * @param length the number of leading hex characters to keep
38	     * @return the upper-case hex prefix of the digest
39	     */
40	    public static String hexPrefix(String input, int length) {
41	        StringBuilder hex = new StringBuilder(length);
42	        byte[] digest = digest(input);
43	        for (int i = 0; hex.length() < length; i++) {
44	            hex.append(String.format("%02X", digest[i]));
45	        }
46	        return hex.substring(0, length);
47	    }
48	
49	    /**
50	     * Produce the full SHA-256 digest of the UTF-8 bytes of {@code input} as 64 lower-case hex
51	     * characters.
52	     *
53	     * @param input the value to hash
54	     * @return the lower-case hex encoding of the whole digest
55	     */
56	    public static String hex(String input) {
57	        byte[] digest = digest(input);
58	        StringBuilder hex = new StringBuilder(digest.length * 2);
59	        for (byte b : digest) {
60	            hex.append(String.format("%02x", b));
61	        }
62	        return hex.toString();
63	    }
64	
65	    private static byte[] digest(String input) {
66	        try {
67	            return MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
68	        } catch (NoSuchAlgorithmException ex) {
69	            // SHA-256 is required to be available on every JVM, so this cannot happen.
70	            throw new IllegalStateException("SHA-256 algorithm not available", ex);
71	        }
72	    }
73	}
