16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Set;
19	
20	/**
21	 * Derives an owner's marketing segment, formatted {@code '<TIER>_<AREA>'}.
22	 *
23	 * <p>The {@code TIER} is {@code PREMIUM} when the owner's membership level is
24	 * {@value #PREMIUM_MIN_LEVEL} or more, otherwise {@code STANDARD}. The
25	 * {@code AREA} is {@code METRO} when the owner's locality is one of the known
26	 * metro regions ({@code NSW}, {@code VIC} or {@code QLD}), otherwise
27	 * {@code REGIONAL}.
28	 */
29	public final class OwnerSegment {
30	
31	    /** Membership level at or above which an owner is in the {@code PREMIUM} tier. */
32	    private static final int PREMIUM_MIN_LEVEL = 3;
33	
34	    /** The localities classified as {@code METRO}; any other locality is {@code REGIONAL}. */
35	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
36	
37	    private OwnerSegment() {
38	    }
39	
40	    /**
41	     * Return the {@code '<TIER>_<AREA>'} segment for the given membership level and
42	     * locality.
43	     *
44	     * @param membershipLevel the owner's membership level (may be {@code null})
45	     * @param locality the owner's canonical region (may be {@code null})
46	     * @return one of {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"},
47	     * {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}
48	     */
49	    public static String of(Integer membershipLevel, String locality) {
50	        return tier(membershipLevel) + "_" + area(locality);
51	    }
52	
53	    private static String tier(Integer membershipLevel) {
54	        return membershipLevel != null && membershipLevel >= PREMIUM_MIN_LEVEL ? "PREMIUM" : "STANDARD";
55	    }
56	
57	    private static String area(String locality) {
58	        return METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
59	    }
60	}
