28	/**
29	 * Emits audit trail entries for {@link Owner} lifecycle events to the dedicated
30	 * {@code AUDIT} logger, keeping audit side-effects separate from request
31	 * handling and persistence logic.
32	 */
33	@Component
34	public class OwnerAuditor {
35	
36	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
37	
38	    private static final ObjectMapper MAPPER = JsonMapper.builder().build();
39	
40	    /** Monotonically increasing sequence number assigned to each create event. */
41	    private final AtomicLong sequence = new AtomicLong();
42	
43	    /**
44	     * Record that an owner was successfully created, capturing its id, customer
45	     * code, (resolved) registration date, membership level and membership
46	     * number. Alongside the human-readable audit line, an immutable structured
47	     * {@link OwnerCreatedEvent} is emitted as JSON.
48	     *
49	     * @param owner the newly persisted owner
50	     */
51	    public void ownerCreated(Owner owner) {
52	        AUDIT.info(
53	            "Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
54	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
55	            owner.getMembershipNumber());
56	        OwnerCreatedEvent event = new OwnerCreatedEvent(this.sequence.incrementAndGet(), owner);
57	        AUDIT.info(MAPPER.writeValueAsString(event));
58	    }
59	}
