18	import java.util.Map;
19	
20	/**
21	 * The fixed postcode-range-to-region lookup.
22	 *
23	 * <p>Maps each region to its inclusive 4-digit postcode range
24	 * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) and
25	 * answers the two questions the application asks of that single table: which
26	 * region a postcode falls in, and whether a region has a known range at all.
27	 * The ranges are disjoint, so a postcode belongs to at most one region.
28	 */
29	public final class PostcodeRegion {
30	
31	    /** Region -> inclusive 4-digit postcode range {@code {low, high}}. */
32	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
33	        "NSW", new int[] {2000, 2099},
34	        "VIC", new int[] {3000, 3099},
35	        "QLD", new int[] {4000, 4099});
36	
37	    private PostcodeRegion() {
38	    }
39	
40	    /**
41	     * Return the region whose range contains the given postcode, or {@code null}
42	     * when the postcode is absent, non-numeric, or in no known range.
43	     *
44	     * @param postcode the postcode to look up (may be {@code null} or blank)
45	     * @return the region string, or {@code null}
46	     */
47	    public static String regionFor(String postcode) {
48	        if (postcode == null || postcode.isBlank()) {
49	            return null;
50	        }
51	        int value;
52	        try {
53	            value = Integer.parseInt(postcode.trim());
54	        }
55	        catch (NumberFormatException ex) {
